    { de: "Er reichte das Führungszeugnis fristgerecht bei der Personalstelle ein.", en: "He handed in the police clearance certificate to HR on time." },
    { de: "Die Behörde schloss den Vorgang nach Vorlage aller Nachweise endgültig ab.", en: "The authority permanently concluded the case after submission of all proofs." }
